chapter(0, 'The phone shell: app bar, tabs and menu', 'Find your way on the phone: Modules cards, the app bar, the bottom tabs, the menu and search.', 'Aarav (Reception)', 'reception', menu='Modules', display='mobile')
read('This is Modules on the phone. The modules are cards instead of a grid, and the red number on a card is the work waiting there.', 'The phone shows the same modules as the PC, laid out for one thumb.', target='sel:.tiles', expect='The module cards for Aarav.', check="has('Welcome, Aarav')")
read('The red bar at the top shows the page title, the business date with Open, a search icon and your initial. The page title changes as you move.', 'The date and the name tell you whose work and which day you are in.', target='sel:header', expect='The app bar with the date 24 Oct.')
read('The tabs at the bottom are Rooms, Arrivals, Bookings, Folios and Menu. They are always there, so one tap takes you to the five most used screens.', 'A receptionist on the floor needs the board, the arrivals and the folios without opening menus.', target='btn:Rooms', expect='The five tabs.')
click('btn:Rooms', 'Tap Rooms.', 'The room board shows every room as a card with its status.', expect='The Room board opens.', check="ctx.page==='rooms'")
click('btn:Arrivals', 'Tap Arrivals.', 'The badge on the tab counts the arrivals still to check in.', expect='The arrivals list opens.', check="ctx.page==='arrivals'")
click('btn:Bookings', 'Tap Bookings.', 'Bookings is the reservation list with its filters.', expect='The bookings list opens.')
click('btn:Folios', 'Tap Folios.', 'Folios opens the guest bills.', expect='The folios list opens.')
click('btn:Menu', 'Tap Menu.', 'The menu lists all modules, the display mode, Change my PIN and Sign out.', expect='The menu opens.', check="has('Sign out')")
click('btn:Close menu', 'Tap Close menu.', 'The menu closes and you stay on the same screen.', expect='The menu is closed.')
click('aria:Search', 'Tap the magnifier in the app bar to search.', 'Search finds any page or action by a few letters.', expect='The search box opens.', check="!!q('.search-box')")
typ('sel:.search-box input', 'folio', 'Type folio.', 'Only pages you may open are offered.', expect='Matching pages are listed.')
press('Escape', 'Press the back key or Escape to close the search.', 'Back always closes the top-most sheet first.', target='sel:header', expect='The search is closed.', check="!q('.search-box')")
